insert into public.grammar_topics (slug, title, summary, tip_tr, example, difficulty) values
  ('be-am-is-are', 'To be: am / is / are', 'Use am with I, is with he/she/it, are with you/we/they for identity, feelings, and location.', 'I am · he/she/it is · you/we/they are', 'I am a student. She is tired. They are at home.', 1),
  ('subject-pronouns', 'Subject pronouns', 'I, you, he, she, it, we, they replace the subject of a sentence.', 'I / you / he / she / it / we / they', 'Ali is here. He is here.', 1),
  ('possessive-adjectives', 'Possessive adjectives', 'my, your, his, her, its, our, their come before a noun to show ownership.', 'my book · her name · their car', 'This is my bag. That is her phone.', 1),
  ('articles-a-an', 'Articles: a / an', 'a/an = one (not specific). Use an before a vowel sound.', 'a book · an apple · an hour (sesli harf sesi)', 'I need a pen and an eraser.', 1),
  ('articles-a-an-the', 'Articles: a / an / the', 'a/an = one (not specific). the = specific / known to speaker and listener.', 'a/an = belirsiz · the = belirli', 'I bought an apple and the apple was sweet.', 1),
  ('plurals', 'Plural nouns', 'Most nouns add -s/-es. Watch irregular plurals (child → children, mouse → mice).', 'book → books · box → boxes · child → children', 'Two books, three boxes, five children.', 1),
  ('this-that-these-those', 'Demonstratives: this / that / these / those', 'this/these = near; that/those = far. this/that singular; these/those plural.', 'this/these = yakın · that/those = uzak', 'This book is mine. Those cars are expensive.', 1),
  ('there-is-are', 'There is / there are', 'Use there is + singular and there are + plural to say something exists.', 'There is a… · There are two…', 'There is a café nearby. There are many students.', 1),
  ('have-has', 'Have / has', 'have with I/you/we/they; has with he/she/it for possession.', 'I have · she has', 'I have a bike. She has two cats.', 1),
  ('present-simple', 'Present Simple', 'Use Present Simple for habits, routines, and facts. Add -s/-es with he/she/it.', 'Alışkanlık ve gerçekler: I work / she works.', 'She goes to school every day.', 1),
  ('present-simple-neg-q', 'Present Simple: negatives & questions', 'Negatives and questions use do/does + base verb.', 'don''t/doesn''t + V1 · Do/Does + özne + V1?', 'She doesn''t like tea. Do you live here?', 1),
  ('present-continuous', 'Present Continuous', 'Use am/is/are + verb-ing for actions happening now or around now.', 'Şu an: am/is/are + V-ing', 'They are playing football right now.', 1),
  ('can-cant', 'Can / can''t (ability & permission)', 'can + base verb for ability or permission; can''t for inability or refusal.', 'can + V1 · can''t = cannot', 'I can swim. Can I open the window?', 1),
  ('imperatives', 'Imperatives', 'Use the base verb to give orders, requests, and instructions. Don''t + verb for negatives.', 'Open the door. · Don''t run.', 'Sit down. Don''t touch that.', 1),
  ('in-on-at', 'Prepositions: in / on / at (place)', 'in = enclosed space; on = surface; at = exact point.', 'in = içinde · on = üzerinde · at = noktada', 'She is at school. The book is on the table. We live in Ankara.', 1),
  ('prepositions-time', 'Prepositions of time', 'in + months/years/parts of day; on + days/dates; at + clock times / night.', 'in July · on Monday · at 7 o''clock', 'I was born in 2005. See you on Friday at 6.', 1),
  ('wh-questions', 'Wh- questions', 'who, what, where, when, why, how ask for specific information.', 'Who / What / Where / When / Why / How', 'Where do you live? Why are you late?', 1),
  ('adjectives-basic', 'Adjectives (basic)', 'Adjectives describe nouns and usually come before the noun or after be.', 'a big house · She is happy.', 'It is a cold day. The film was boring.', 1),
  ('adverbs-frequency', 'Adverbs of frequency', 'always, usually, often, sometimes, rarely, never usually go before the main verb (after be).', 'always → never · be''den sonra, diğer fiilden önce', 'She always arrives early. He is never late.', 1),
  ('object-pronouns', 'Object pronouns', 'me, you, him, her, it, us, them replace the object of a verb or preposition.', 'me / him / her / us / them', 'Call me. I saw them yesterday.', 1),
  ('possessive-s', 'Possessive ''s', 'Add ''s to a person/animal to show ownership. Plural ending in s takes only ''.', 'Ali''s bag · the students'' books', 'This is Sara''s phone. The boys'' room is tidy.', 1),
  ('possessive-pronouns', 'Possessive pronouns', 'mine, yours, his, hers, ours, theirs replace a noun phrase (not followed by a noun).', 'This is mine. · That bag is hers. (my book ≠ mine)', 'Is this pen yours? No, it''s mine.', 1),
  ('have-got', 'Have got / has got', 'have got = have (possession), common in British English; questions with have…got?', 'I''ve got · she''s got · Have you got…?', 'I''ve got two brothers. Has she got a car?', 1),
  ('be-questions-short-answers', 'Be: questions & short answers', 'Invert be for yes/no questions; answer with Yes/No + pronoun + be (not the full verb).', 'Are you ready? — Yes, I am. / No, I''m not.', 'Is she a teacher? Yes, she is.', 1),
  ('and-but-or-because', 'And / but / or / because', 'Basic conjunctions join ideas: and (add), but (contrast), or (choice), because (reason).', 'and · but · or · because', 'I stayed home because it rained.', 1),
  ('like-love-hate-ing', 'Like / love / hate + -ing', 'After like, love, enjoy, hate, prefer use verb-ing for general preferences.', 'like + V-ing · I love swimming.', 'She hates getting up early. We enjoy cooking.', 1),
  ('want-need-would-like', 'Want / need / would like + to', 'want/need/would like + to + verb for desires and needs; would like is more polite.', 'want to go · need to study · I''d like to…', 'I want to learn English. I''d like to order tea.', 1),
  ('prepositions-movement', 'Prepositions of movement', 'to, from, into, out of, onto, off, through, across, along describe direction.', 'to school · into the room · across the street', 'She walked into the café. He ran across the park.', 1),
  ('how-much-how-many', 'How much / how many', 'how many + countable plural; how much + uncountable (and for price).', 'How many books? · How much water/money?', 'How many students are there? How much is it?', 1),
  ('whose', 'Whose', 'whose asks about ownership; answer with possessive adjective/pronoun or ''s.', 'Whose bag is this? — It''s Ali''s. / It''s mine.', 'Whose phone is ringing?', 1),
  ('lets-suggestions', 'Let''s / shall we (suggestions)', 'Let''s + verb suggests doing something together; Shall we…? is a polite alternative.', 'Let''s go. · Shall we start?', 'Let''s watch a film. Shall we meet at 6?', 1),
  ('present-simple-vs-continuous', 'Present Simple vs Continuous', 'Habits/facts → Present Simple. Happening now / temporary → Present Continuous.', 'every day → Simple · now/at the moment → Continuous', 'I usually walk, but today I''m taking the bus.', 1),
  ('stative-verbs', 'Stative verbs', 'Know, like, want, believe, own… describe states and are rarely used in continuous forms.', 'I know (not I''m knowing) · I want / I like / I believe', 'I understand the rule. She owns a flat in Izmir.', 1),
  ('prepositions-place-extra', 'Prepositions of place (next to / between…)', 'next to, between, opposite, behind, in front of, under, above, near describe position.', 'next to · between · opposite · behind · in front of', 'The bank is opposite the park, next to the café.', 1),
  ('by-transport', 'By / on (transport)', 'by + means of transport (by bus/car/train); on foot; on the bus/train when inside.', 'by bus · by car · on foot · on the train', 'I go to work by metro. We came on foot.', 1),
  ('telling-the-time', 'Telling the time', 'o''clock, half past, quarter past/to; at + clock time; a.m./p.m. or 24-hour style.', 'at 7 o''clock · half past two · quarter to nine', 'The class starts at half past nine.', 1),
  ('past-simple', 'Past Simple', 'Use Past Simple for finished actions in the past. Regular verbs take -ed; many are irregular.', 'Bitmiş geçmiş: V2 (worked / went)', 'I watched a movie last night.', 2),
  ('past-simple-irregular', 'Past Simple: irregular verbs', 'Common irregulars: go→went, see→saw, have→had, make→made, take→took.', 'go–went · see–saw · take–took · make–made', 'She went home. He took the bus.', 2),
  ('past-continuous', 'Past Continuous', 'was/were + V-ing for an action in progress at a past moment (often interrupted).', 'was/were + V-ing', 'I was cooking when she called.', 2),
  ('going-to', 'Future: be going to', 'am/is/are + going to + verb for plans and predictions from present evidence.', 'be + going to + V1', 'I''m going to study tonight. Look at those clouds — it''s going to rain.', 2),
  ('will-future', 'Future: will', 'will + base verb for instant decisions, offers, promises, and predictions.', 'will + V1 · won''t = will not', 'I''ll help you. It will be sunny tomorrow.', 2),
  ('present-continuous-future', 'Present Continuous for future', 'am/is/are + V-ing for fixed personal arrangements in the near future.', 'Yarınki randevu: I''m meeting Ali at 5.', 'We''re flying to Izmir on Friday.', 2),
  ('present-perfect', 'Present Perfect', 'have/has + past participle for life experience and actions linked to now (for/since).', 'have/has + V3 · for / since', 'She has lived in London since 2010.', 2),
  ('present-perfect-vs-past', 'Present Perfect vs Past Simple', 'Present Perfect = unfinished time / result now. Past Simple = finished time (yesterday, in 2019).', 'ever/never/just → Perfect · yesterday/last… → Past', 'I have seen that film. I saw it last week.', 2),
  ('comparatives', 'Comparatives', 'Compare two things: adj + -er + than, or more + adj + than for longer adjectives.', 'taller than · more interesting than · better/worse', 'This bag is cheaper than that one.', 2),
  ('superlatives', 'Superlatives', 'the + adj-est or the most + adj to say something is number one in a group.', 'the tallest · the most expensive · the best', 'She is the fastest runner in the class.', 2),
  ('countable-uncountable', 'Countable & uncountable nouns', 'Countable have singular/plural (a book / books). Uncountable have no plural (water, advice, information).', 'a/an/many + sayıla bilir · much/some + sayılamaz', 'I need some water and two apples.', 2),
  ('some-any-much-many', 'Some / any / much / many', 'some (positive), any (questions/negatives); many + countable, much + uncountable.', 'some (+) · any (?/–) · many books · much time', 'Do you have any sugar? I don''t have much time.', 2),
  ('modals-obligation', 'Must / have to / should', 'must/have to = obligation; should = advice; mustn''t = prohibition; don''t have to = no need.', 'must/have to = zorunluluk · should = tavsiye', 'You should sleep more. You mustn''t smoke here.', 2),
  ('could-would', 'Could / would', 'could = past ability / polite request; would like = polite want; would = hypothetical.', 'Could you…? · I''d like… · I could swim (geçmiş)', 'Could you help me? I''d like a coffee.', 2),
  ('first-conditional', 'First conditional', 'If + Present Simple, will + verb for real future possibilities.', 'If it rains, I will stay home.', 'If you study, you will pass.', 2),
  ('gerunds-infinitives', 'Gerunds & infinitives', 'Some verbs take -ing (enjoy swimming); others take to + verb (want to go).', 'enjoy + V-ing · want + to V', 'I enjoy reading. She wants to travel.', 2),
  ('relative-who-which', 'Relative pronouns: who / which / that', 'who = people; which = things; that = people or things in defining clauses.', 'who = kişi · which = şey · that = ikisi', 'The man who called is my teacher.', 2),
  ('articles-the', 'Articles: the (specific use)', 'the for unique things, second mention, superlatives, and known shared context.', 'the sun · the first one · the same café', 'The moon is bright tonight.', 2),
  ('adverbs-manner', 'Adverbs of manner', 'Many adverbs add -ly to adjectives (quick → quickly) and say how something happens.', 'slow → slowly · careful → carefully · fast/hard (aynı)', 'She speaks English clearly.', 2),
  ('used-to', 'Used to', 'used to + verb for past habits or states that are no longer true.', 'used to + V1 (eskiden … yapardım)', 'I used to play tennis every week.', 2),
  ('past-simple-vs-continuous', 'Past Simple vs Continuous', 'Past Continuous = background/in progress; Past Simple = finished interrupting action.', 'I was reading when the phone rang.', 'While she was cooking, he set the table.', 2),
  ('will-vs-going-to', 'Will vs be going to', 'going to = plan/evidence; will = instant decision, offer, promise, or general prediction.', 'plan → going to · karar anı/teklif → will', 'I''m going to visit Mum. Oh, I''ll come too!', 2),
  ('zero-conditional', 'Zero conditional', 'If + Present, Present for facts and general truths (always true).', 'If you heat ice, it melts.', 'If people don''t drink water, they get thirsty.', 2),
  ('indefinite-pronouns', 'Someone / anyone / nothing…', 'someone/anyone/everyone/no one; something/anything…; somewhere/anywhere…', 'someone (+) · anyone (?/–) · nothing = not anything', 'Someone called. I didn''t see anyone. There''s nothing here.', 2),
  ('reflexive-pronouns', 'Reflexive pronouns', 'myself, yourself, himself… when subject and object are the same; also for emphasis.', 'myself / yourself / themselves · by myself = alone', 'She hurt herself. I fixed it myself.', 2),
  ('each-other', 'Each other / one another', 'each other (and one another) for reciprocal actions between two or more people.', 'They help each other.', 'We send each other messages every day.', 2),
  ('adjective-prepositions', 'Adjective + preposition', 'Fixed pairs: good at, interested in, afraid of, famous for, similar to, different from.', 'good at · interested in · afraid of · keen on', 'She''s good at maths. I''m interested in history.', 2),
  ('verb-prepositions', 'Verb + preposition', 'listen to, wait for, depend on, look for, belong to, talk about — learn as chunks.', 'listen to · wait for · look for · belong to', 'I''m waiting for the bus. It depends on the weather.', 2),
  ('already-yet-just-still', 'Already / yet / just / still', 'just/already often with Present Perfect; yet in questions/negatives; still = continuing.', 'just/already · yet (?/–) · still (hâlâ)', 'I''ve just finished. Have you eaten yet? She''s still working.', 2),
  ('ago', 'Ago', 'ago goes after a past time period and is used with Past Simple (not Present Perfect).', 'two days ago · (Present Perfect ile kullanılmaz)', 'I met her three years ago.', 2),
  ('may-might', 'May / might', 'may/might + verb = possibility; may also for polite permission.', 'might rain · May I sit here?', 'It might snow later. You may leave early.', 2),
  ('question-tags', 'Question tags', 'Short tags (isn''t it?, don''t you?) check or confirm; polarity usually opposite to the statement.', 'You''re tired, aren''t you? · She doesn''t drive, does she?', 'It''s cold, isn''t it? Let''s go, shall we?', 2),
  ('make-vs-do', 'Make vs do', 'do = tasks/activities (homework, exercise); make = create/produce (a cake, a decision, a mistake).', 'do homework · make a cake / a mistake', 'I did the washing-up. She made a reservation.', 2),
  ('say-vs-tell', 'Say vs tell', 'tell needs a person (tell me); say focuses on the words (say that… / say to someone).', 'tell someone · say something (to someone)', 'She told me the truth. He said he was busy.', 2),
  ('adverbs-degree', 'Adverbs of degree', 'very, really, quite, a bit, too modify adjectives and other adverbs.', 'very tired · quite good · a bit late', 'The exam was really hard. It''s quite warm today.', 2),
  ('adjective-order', 'Adjective order', 'Opinion before fact; typical order: opinion → size → age → colour → origin → material → purpose.', 'a lovely small old red Italian leather bag', 'She bought a beautiful new black dress.', 2),
  ('as-as-equality', 'As… as (equality)', 'as + adjective/adverb + as for equal comparison; not as/so… as for inequality.', 'as tall as · not as expensive as', 'She is as tall as her brother. This isn''t as hard as I thought.', 2),
  ('comparative-adverbs', 'Comparative adverbs', 'Compare how actions happen: -er / more + adverb + than; irregular: better, worse, further.', 'faster than · more carefully · better/worse', 'She drives more carefully than I do.', 2),
  ('during-for-while', 'During / for / while', 'during + noun; for + period; while + clause (action in progress).', 'during the lesson · for two hours · while I was cooking', 'I slept during the film. I waited for an hour while she shopped.', 2),
  ('by-vs-until', 'By vs until', 'by = not later than a deadline; until/till = up to a point, then stopping.', 'by Friday = en geç · until Friday = Cuma''ya kadar', 'Finish it by Monday. I''ll stay until 6.', 2),
  ('like-vs-as', 'Like vs as', 'like + noun = similar to; as + noun = in the role of; as + clause also for manner.', 'She sings like a bird. · He works as a teacher.', 'Do it as I showed you. It looks like rain.', 2),
  ('ed-ing-adjectives', '-ed / -ing adjectives', '-ing describes the cause (boring film); -ed describes the feeling (bored students).', 'interesting / interested · boring / bored · tiring / tired', 'The lesson was interesting. The students were interested.', 2),
  ('mustnt-vs-dont-have-to', 'Mustn''t vs don''t have to', 'mustn''t = prohibition; don''t have to / needn''t = no obligation (you can if you want).', 'mustn''t = yasak · don''t have to = gerek yok', 'You mustn''t park here. You don''t have to come if you''re busy.', 2),
  ('shall', 'Shall (offers & suggestions)', 'Shall I…? offers help; Shall we…? suggests; mainly British English, first person.', 'Shall I open the window? · Shall we dance?', 'Shall I carry that bag for you?', 2),
  ('get-passive-basic', 'Get + adjective / get + V3', 'get + adjective = become; get + past participle = informal passive / change of state.', 'get tired · get married · get stolen (günlük)', 'I''m getting hungry. My phone got stolen.', 2),
  ('present-perfect-continuous', 'Present Perfect Continuous', 'have/has been + V-ing for actions that started in the past and continue, or just stopped with a visible result.', 'have/has been + V-ing', 'I have been waiting for an hour.', 3),
  ('past-perfect', 'Past Perfect', 'had + V3 for an action completed before another past action.', 'had + V3 (önce bitmiş geçmiş)', 'She had left before I arrived.', 3),
  ('past-perfect-continuous', 'Past Perfect Continuous', 'had been + V-ing for a continuous action before a past point.', 'had been + V-ing', 'He had been working all day before the meeting.', 3),
  ('future-continuous', 'Future Continuous', 'will be + V-ing for an action in progress at a future time.', 'will be + V-ing', 'This time tomorrow I will be flying to Rome.', 3),
  ('future-perfect', 'Future Perfect', 'will have + V3 for an action completed before a future deadline.', 'will have + V3', 'By Friday I will have finished the report.', 3),
  ('second-conditional', 'Second conditional', 'If + Past Simple, would + verb for unreal or unlikely present/future situations.', 'If I were rich, I would travel.', 'If I had more time, I would learn piano.', 3),
  ('third-conditional', 'Third conditional', 'If + Past Perfect, would have + V3 for unreal past (regret / different past).', 'If I had studied, I would have passed.', 'If she had left earlier, she would have caught the train.', 3),
  ('passive-voice', 'Passive voice', 'be + V3 when the focus is on the action/result, not the doer (by + agent optional).', 'be + V3 · The letter was sent.', 'English is spoken here. The cake was made by Tom.', 3),
  ('reported-speech', 'Reported speech', 'Backshift tenses when reporting past statements; change pronouns and time words.', 'am → was · will → would · today → that day', 'She said she was tired. He told me he would call.', 3),
  ('relative-clauses', 'Relative clauses', 'Defining clauses identify the noun; non-defining add extra info and use commas.', 'tanımlayan (virgülsüz) · ek bilgi (virgüllü)', 'My brother, who lives in Berlin, is a doctor.', 3),
  ('modals-deduction', 'Modals of deduction', 'must = certainty; might/may/could = possibility; can''t = impossibility (about now).', 'must be · might be · can''t be', 'He must be at work. That can''t be true.', 3),
  ('wish-if-only', 'Wish / if only', 'wish + Past Simple (present regret); wish + Past Perfect (past regret); wish + would (annoyance).', 'I wish I knew · I wish I had gone', 'I wish I spoke French. If only I had listened.', 3),
  ('so-such', 'So / such', 'so + adjective/adverb; such + (a/an) + adjective + noun for emphasis.', 'so tired · such a long day', 'It was so cold. It was such a cold night.', 3),
  ('enough-too', 'Enough / too', 'too = more than wanted; enough = as much as needed (adj + enough / enough + noun).', 'too heavy · tall enough · enough money', 'This bag is too heavy. I''m not tall enough.', 3),
  ('both-either-neither', 'Both / either / neither', 'both = the two; either = one or the other; neither = not one and not the other.', 'both of them · either option · neither works', 'Both answers are correct. Neither team scored.', 3),
  ('quantifiers', 'Quantifiers (few / little / plenty)', 'a few/few + countable; a little/little + uncountable; plenty of = more than enough.', 'a few friends · little time · plenty of food', 'I have a few ideas but little money.', 3),
  ('linking-words', 'Linking words', 'although, however, therefore, because, so, while connect ideas logically.', 'although / however / therefore / because', 'Although it rained, we went out.', 3),
  ('phrasal-verbs', 'Phrasal verbs', 'Verb + particle with a special meaning (look up, give up, turn on). Some are separable.', 'look up · give up · turn on (ayrılabilir olanlar)', 'Please turn the lights off. She gave up smoking.', 3),
  ('be-used-to-get-used-to', 'Be used to / get used to', 'be used to + noun/-ing = accustomed; get used to = becoming accustomed (≠ used to + V1).', 'I''m used to waking early. · I''m getting used to it.', 'She''s used to the noise. You''ll get used to driving here.', 3),
  ('time-clauses', 'Time clauses (when / until / as soon as…)', 'when, while, before, after, until, as soon as, once + Present for future time (not will).', 'When I arrive, I''ll call. (will yok yan cümlede)', 'I''ll wait until she finishes. Call me as soon as you land.', 3),
  ('purpose-clauses', 'Purpose: to / in order to / so that', 'to / in order to / so as to + verb; so that + clause (often with can/will).', 'to learn · in order to pass · so that I can…', 'I study to improve. I left early so that I wouldn''t be late.', 3),
  ('contrast-clauses', 'Contrast: although / despite / while', 'although/even though + clause; despite/in spite of + noun/-ing; while/whereas for contrast.', 'although it rained · despite the rain · whereas', 'Although he was tired, he continued. Despite the rain, we went out.', 3),
  ('prefer-would-rather', 'Prefer / would rather', 'prefer A to B; would rather + base verb; would prefer to + verb.', 'prefer tea to coffee · I''d rather stay · I''d prefer to go', 'I''d rather walk than take a taxi.', 3),
  ('indirect-questions', 'Indirect questions', 'Polite questions keep statement word order after if/whether or a wh- word (no do-support).', 'Could you tell me where the station is? (is the station değil)', 'Do you know if she''s coming? I wonder what time it starts.', 3),
  ('another-other-others', 'Another / other / others / the other', 'another + singular; other + plural/uncountable; others = other ones; the other = the remaining.', 'another day · other people · the other one · others', 'I need another pen. Where are the others?', 3),
  ('each-every-all-whole', 'Each / every / all / whole', 'each/every + singular; all + plural/uncountable; whole/entire often with the + singular noun.', 'each student · every day · all the time · the whole day', 'Every child needs care. We spent the whole weekend studying.', 3),
  ('so-neither-agreement', 'So / neither (agreement)', 'So do I / Neither do I to agree with positive/negative statements; invert auxiliary + subject.', 'So do I. · Neither have I. · Me too / Me neither (günlük)', 'I love jazz. — So do I. I don''t eat meat. — Neither do I.', 3),
  ('its-time', 'It''s time / it''s high time', 'It''s time + to-infinitive, or It''s (high) time + Past Simple for overdue action.', 'It''s time to go. · It''s time we left.', 'It''s high time you started revising.', 3),
  ('verbs-of-perception', 'Verbs of perception', 'see/hear/watch/feel + object + bare infinitive (complete) or -ing (in progress).', 'I saw her leave. · I saw her leaving.', 'I heard him sing. I heard him singing in the shower.', 3),
  ('look-forward-to', 'Look forward to + -ing', 'look forward to is a fixed phrase; to is a preposition, so use noun or -ing (not infinitive).', 'look forward to seeing you (to + V-ing)', 'I''m looking forward to meeting your family.', 3),
  ('had-better', 'Had better', 'had better + base verb for strong advice/warning about now or the near future.', 'you''d better go · you''d better not be late', 'You''d better take an umbrella. It looks like rain.', 3),
  ('for-since', 'For / since', 'for + period (for two years); since + starting point (since 2020 / since Monday).', 'for = süre · since = başlangıç noktası', 'I''ve lived here for five years / since 2019.', 3),
  ('present-perfect-vs-continuous', 'Present Perfect vs Perfect Continuous', 'Simple Perfect often focuses on result/amount; Continuous on duration/activity itself.', 'I''ve written three emails. · I''ve been writing all morning.', 'She''s read the book. She''s been reading for hours.', 3),
  ('gerunds-infinitives-change', 'Gerund vs infinitive (meaning change)', 'stop/remember/forget/try/regret change meaning with -ing vs to-infinitive.', 'stop smoking ≠ stop to smoke · remember doing ≠ remember to do', 'I stopped to buy water. I stopped buying water.', 3),
  ('verb-object-infinitive', 'Verb + object + to-infinitive', 'want/ask/tell/advise/allow/expect + object + to + verb.', 'want someone to… · tell someone to… · allow someone to…', 'She asked me to wait. They allowed us to leave early.', 3),
  ('make-let-help', 'Make / let / help + infinitive', 'make/let + object + bare infinitive; help + bare or to-infinitive.', 'make me do · let me go · help me (to) carry', 'The teacher made us rewrite it. Let me explain.', 3),
  ('would-past-habits', 'Would for past habits', 'would + verb for typical past behaviour (like used to), but not usually for past states.', 'Every summer we would go camping. (durum için used to)', 'On Sundays he would visit his grandparents.', 3),
  ('probability-adverbs', 'Probability adverbs', 'certainly, probably, possibly, definitely, maybe/perhaps place before the main verb (after be).', 'She''ll probably come. · He''s definitely right.', 'They will certainly win. Maybe she''s late.', 3),
  ('reason-clauses', 'Reason: because / as / since', 'because (strong reason); as/since often for known reasons, sometimes more formal.', 'because · as · since (= çünkü)', 'As it was late, we took a taxi. Since you''re here, let''s start.', 3),
  ('so-that-result', 'So… that / such… that (result)', 'so + adj/adv + that; such + (a/an) + adj + noun + that express result.', 'so tired that… · such a good film that…', 'It was so cold that the lake froze.', 3),
  ('mixed-conditionals', 'Mixed conditionals', 'Mix past and present unreal forms: past cause → present result, or present condition → past result.', 'If I had…, I would be… (geçmiş → şimdi)', 'If I had studied medicine, I would be a doctor now.', 4),
  ('causative', 'Causative: have / get something done', 'have/get + object + V3 when someone else does the action for you.', 'have/get + nesne + V3', 'I had my hair cut. She got her car repaired.', 4),
  ('advanced-passive', 'Advanced passive', 'Passive with modals, reporting verbs (it is said that…), and get-passive.', 'It is said that… · The window got broken.', 'It is believed that the company will expand.', 4),
  ('reported-questions', 'Reported questions & commands', 'No do-support; use if/whether for yes-no; ask/tell + object + to-infinitive for commands.', 'He asked where I lived. · She told me to wait.', 'She asked if I was ready. He told us to sit down.', 4),
  ('modals-perfect', 'Modals + perfect infinitive', 'must/might/should/could + have + V3 for past deduction, advice, and possibility.', 'must have · should have · could have', 'You should have called. He must have forgotten.', 4),
  ('future-in-the-past', 'Future in the past', 'was/were going to, would, was about to for planned or expected future from a past viewpoint.', 'was going to · would · was about to', 'I was going to call, but my phone died.', 4),
  ('participle-clauses', 'Participle clauses', 'Use -ing / -ed clauses to shorten relative or adverbial clauses.', 'Walking home, I met Ali. · Built in 1900,…', 'Feeling tired, she went to bed early.', 4),
  ('relative-advanced', 'Advanced relative clauses', 'whose, where, when, why; preposition + which/whom; reduced relatives.', 'whose · of which · the man I met', 'The woman whose car was stolen called the police.', 4),
  ('inversion-conditionals', 'Inversion in conditionals', 'Formal: Had I known… / Were I you… / Should you need… instead of if-clauses.', 'Had I known… = If I had known…', 'Had I known, I would have helped.', 4),
  ('cleft-sentences', 'Cleft sentences', 'It is/was … that/who and What … is/was to emphasize one part of a sentence.', 'It was Ali who called. · What I need is rest.', 'It was yesterday that we met.', 4),
  ('discourse-markers', 'Discourse markers', 'anyway, actually, on the other hand, in contrast, furthermore structure spoken and written argument.', 'however · furthermore · on the other hand', 'On the other hand, costs may rise.', 4),
  ('noun-phrases', 'Complex noun phrases', 'Stack determiners, adjectives, and of-phrases to pack information into one noun group.', 'the sudden rise in prices · a well-known expert', 'The rapid growth of online shopping surprised analysts.', 4),
  ('future-perfect-continuous', 'Future Perfect Continuous', 'will have been + V-ing for duration up to a future point.', 'will have been + V-ing', 'By June I will have been working here for five years.', 4),
  ('narrative-tenses', 'Narrative tenses', 'Combine Past Simple, Continuous, Perfect, and Perfect Continuous to tell a story clearly.', 'olay = Past Simple · arka plan = Continuous · önce = Perfect', 'I had been waiting when the train finally arrived.', 4),
  ('as-if-as-though', 'As if / as though', 'as if/as though introduce unreal or seeming situations; often Past for present unreality.', 'He talks as if he knew everything.', 'She looked as though she had seen a ghost.', 4),
  ('whatever-whoever', 'Whatever / whoever / wherever…', 'wh-ever words mean ''any…'' or ''it doesn''t matter which/who/where''.', 'whatever · whoever · wherever · whenever · however', 'Wherever you go, take a map. Call me whenever you need help.', 4),
  ('correlative-conjunctions', 'Not only… but also / either… or', 'Paired conjunctions: not only…but also, either…or, neither…nor, both…and; watch inversion after not only.', 'not only… but also · either… or · neither… nor', 'Not only did she pass, but she also got top marks.', 4),
  ('the-the-comparatives', 'The… the… comparatives', 'the + comparative, the + comparative shows two things changing together.', 'The more you practise, the better you get.', 'The sooner we leave, the earlier we''ll arrive.', 4),
  ('be-supposed-to', 'Be supposed to / be meant to', 'be supposed to = expected/required (often vs reality); be meant to = intended purpose.', 'You''re supposed to wear a helmet.', 'This film is meant to be funny. I''m supposed to be at work!', 4),
  ('distancing', 'Distancing (seem / appear / apparently)', 'Use seem/appear, reportedly, apparently, it is said to soften claims and add distance.', 'It seems that… · She appears to be… · Apparently…', 'He appears to have left. Apparently the meeting was cancelled.', 4),
  ('dependent-prepositions', 'Dependent prepositions (advanced)', 'Noun/adjective/verb + fixed preposition patterns: advantage of, capable of, accuse of, consist of…', 'aware of · capable of · succeed in · result in', 'She was accused of cheating. Success consists of hard work.', 4),
  ('be-about-to-due-to', 'Be about to / due to / to + V', 'be about to = immediate future; be due to = scheduled; be to = official arrangement.', 'about to leave · due to arrive · are to report', 'The train is about to leave. She is due to speak at 3.', 4),
  ('neednt-have-vs-didnt-need', 'Needn''t have vs didn''t need to', 'didn''t need to = wasn''t necessary (maybe not done); needn''t have = done but unnecessary.', 'didn''t need to go · needn''t have gone (gittim ama gerek yokmuş)', 'I didn''t need to cook — there was leftovers. I needn''t have cooked so much!', 4),
  ('modal-continuous', 'Modals + continuous / perfect continuous', 'must/might/should + be + V-ing (now); + have been + V-ing (past duration).', 'must be joking · might have been waiting', 'She must be studying. He might have been sleeping.', 4),
  ('it-cleft-adj', 'It is + adjective + that / to', 'It is important/essential/likely that… or to-infinitive to evaluate ideas formally.', 'It is important that… · It is likely to…', 'It is essential that everyone arrives on time.', 4),
  ('subject-verb-agreement', 'Subject–verb agreement', 'Agreement with collective nouns, either/neither, each, there is/are, and complex subjects.', 'The team is/are… · Neither of them is… · There are…', 'Neither option works. The news is surprising.', 4),
  ('inversion', 'Inversion (negative adverbials)', 'After never, rarely, not only, under no circumstances… invert auxiliary + subject for emphasis.', 'Never have I… · Not only did she…', 'Never have I seen such chaos. Rarely does he complain.', 5),
  ('subjunctive', 'Subjunctive', 'Base verb after suggest/recommend/insist that… and in formal phrases (God save…, be that as it may).', 'I suggest that he go… (bare infinitive)', 'They recommended that she apply early.', 5),
  ('nominalisation', 'Nominalisation', 'Turn verbs/adjectives into nouns for a more academic, formal style.', 'decide → decision · develop → development', 'Their decision to expand led to rapid growth.', 5),
  ('ellipsis-substitution', 'Ellipsis & substitution', 'Omit repeated words or replace them with so/do/one to avoid repetition.', 'I think so. · so do I · a red one', 'She can swim and so can I. I''ll take the blue one.', 5),
  ('emphatic-structures', 'Emphatic structures', 'do/does/did for emphasis; fronting; rhetorical inversion for style.', 'I do understand. · Never again will I…', 'I did tell you. What a mess this is!', 5),
  ('advanced-modals', 'Advanced modality & hedging', 'hedges (seem, appear, tend to), probability scales, and formal obligation (be to / be supposed to).', 'seem to · be supposed to · be to', 'Prices appear to be rising. You are to report by noon.', 5),
  ('hypothesis-speculation', 'Hypothesis & speculation', 'suppose, imagine, what if, as if/as though, and speculative modals for nuanced meaning.', 'as if · suppose · might well', 'He talks as if he knew everything. She might well refuse.', 5),
  ('register-formality', 'Register & formality', 'Choose formal vs informal grammar and vocabulary for academic, professional, or casual contexts.', 'Could you…? (resmi) · Can you…? (günlük)', 'I would appreciate your assistance. / Can you help?', 5),
  ('hedging', 'Hedging language', 'Softening claims with tend to, suggest, it could be argued, to some extent, arguably…', 'tend to · suggest that · to some extent · arguably', 'The data suggest that prices may continue to rise.', 5),
  ('fronting', 'Fronting & topicalisation', 'Move an object, adverbial, or complement to the front for emphasis or cohesion.', 'This problem we can solve. · Into the room walked Ali.', 'Such behaviour I will not tolerate.', 5),
  ('absolute-clauses', 'Absolute constructions', 'Noun + participle/adjective phrase adds a circumstance without a full finite clause.', 'Her work finished, she left. · Weather permitting,…', 'The exam over, the students cheered.', 5),
  ('reduced-relative-clauses', 'Reduced relative clauses', 'Drop who/which/that + be, or use -ing/-ed to shorten defining relatives.', 'the man sitting there · the book written by her', 'Anyone interested should apply. The people living next door are noisy.', 5),
  ('parallelism', 'Parallel structure', 'Keep matching forms in lists and paired constructions (to…, to… / -ing, -ing).', 'She likes hiking, swimming, and reading. (aynı biçim)', 'The job requires patience, creativity, and attention to detail.', 5),
  ('apposition', 'Apposition', 'Two noun phrases side by side, the second renaming or adding identity to the first.', 'My friend Ali, a doctor, lives nearby.', 'Istanbul, Turkey''s largest city, is vibrant.', 5),
  ('rather-than-instead-of', 'Rather than / instead of', 'instead of + noun/-ing; rather than often parallels the verb form of the main clause.', 'instead of waiting · rather than wait/waiting', 'Take a taxi instead of walking. Rather than complain, help.', 5),
  ('perfect-infinitive', 'Perfect infinitive (to have + V3)', 'appear/seem/claim + to have + V3 for earlier actions; also after modals in perfect form.', 'seem to have left · claim to have seen', 'She appears to have forgotten. He claimed to have finished.', 5),
  ('stance-adverbials', 'Stance & comment adverbials', 'frankly, clearly, surprisingly, in fact, on the whole signal the speaker''s attitude.', 'frankly · clearly · surprisingly · on the whole', 'Frankly, I disagree. Surprisingly, nobody complained.', 5),
  ('information-structure', 'Given / new information', 'Put known information early and new focus later; use passives, clefts, and fronting for packaging.', 'bilinen → baş · yeni bilgi → son (end-focus)', 'The results were published yesterday. It was the CEO who resigned.', 5),
  ('verbless-clauses', 'Verbless clauses', 'Omit be in subordinate circumstances when meaning stays clear (When in Rome…, If necessary…).', 'If possible… · When young… · Although tired…', 'If necessary, call me. Although exhausted, she smiled.', 5)
